import { DurableObject } from 'cloudflare:workers';
import { Lifecycle } from 'agents/lifecycle';
import { MCPClientManager } from 'agents/mcp/client';

const TOOLS_SERVER_ID = 'tools';

// A plain Durable Object (not an Agent). Our other Workers call listTools() over RPC.
export class ToolGateway extends DurableObject {
  #lifecycle;
  #mcp;

  constructor(ctx, env) {
    super(ctx, env);
    // The manager persists registered servers in this object's SQLite storage
    // and restores (reconnects) them when the lifecycle starts after eviction.
    this.#mcp = new MCPClientManager('tool-gateway', '1.0.0', { env });
    this.#lifecycle = Lifecycle.install(this).use(this.#mcp);
  }

  async listTools() {
    // Native RPC bypasses fetch, so start the lifecycle (and restore connections) explicitly.
    await this.#lifecycle.start();
    if (!this.#mcp.mcpConnections[TOOLS_SERVER_ID]) {
      await this.#mcp.registerServer(TOOLS_SERVER_ID, {
        url: this.env.TOOLS_MCP_URL,
        name: 'tools',
      });
      await this.#mcp.establishConnection(TOOLS_SERVER_ID);
    }
    await this.#mcp.waitForConnections({ timeout: 30_000 });
    return this.#mcp.listTools({ serverId: TOOLS_SERVER_ID });
  }
}

